// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initially owner is address(this) (the test contract)
        address alice = address(0x123);
        // Transfer ownership to alice - reference works, bug sets owner to address(0)
        vm.prank(address(this));
        c.transferOwnership(alice);
        // Now try calling owned() as alice
        vm.prank(alice);
        // This will revert on bug because owner is address(0), but succeed on reference
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
